import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array and multiple hash functions
    to probabilistically determine whether an element is in a set.

    This implementation calculates the optimal bit array size and the number of hash functions
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array (m) and the number of hash functions (k)
        self.size = self._optimal_bit_array_size()
        self.num_hashes = self._optimal_num_hashes()

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculate optimal size of the bit array."""
        return math.ceil(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_num_hashes(self) -> int:
        """Calculate optimal number of hash functions."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate k hash values for the given item."""
        hash_values = []
        for i in range(self.num_hashes):
            hash_val = int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size
            hash_values.append(hash_val)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the bloom filter."""
        for hash_val in self._hashes(item):
            self.bit_array[hash_val] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is potentially in the bloom filter."""
        for hash_val in self._hashes(item):
            if self.bit_array[hash_val] == 0:
                return False
        return True

